SELECT s.id, s.product_id, s.sku_name, s.sku_code, s.price, s.original_price, s.stock, s.warning_stock, s.spec_attributes, s.sku_image, s.weight, s.volume, s.enabled, s.sort_weight, s.marketing_config, s.version, s.tenant_id, s.created_by, s.updated_by, s.created_time, s.updated_time, s.is_deleted, p.merchant_id AS merchant_id FROM product_skus s INNER JOIN products p ON s.product_id = p.id WHERE s.product_id IN
#{productId}
AND s.is_deleted = 0 AND p.is_deleted = 0 ORDER BY s.product_id, s.sort_weight DESC, s.created_time

SELECT s.id, s.product_id, s.sku_name, s.sku_code, s.price, s.original_price, s.stock, s.warning_stock, s.spec_attributes, s.sku_image, s.weight, s.volume, s.enabled, s.sort_weight, s.marketing_config, s.version, s.tenant_id, s.created_by, s.updated_by, s.created_time, s.updated_time, s.is_deleted, p.merchant_id AS merchant_id FROM product_skus s INNER JOIN products p ON s.product_id = p.id WHERE s.id IN
#{skuId}
AND s.is_deleted = 0 AND p.is_deleted = 0

WITH RankedProducts AS ( SELECT p.id AS product_id, p.name AS product_name, p.main_image, p.sort_weight, p.merchant_id, p.updated_time, ROW_NUMBER() OVER (PARTITION BY p.merchant_id ORDER BY p.sort_weight DESC, p.updated_time DESC) AS rn FROM products p WHERE p.is_deleted = 0 AND p.status = 'PUBLISHED' AND p.merchant_id IN
#{mid}
), LowestPriceSku AS ( SELECT s.product_id, s.id AS sku_id, s.price, s.original_price, ROW_NUMBER() OVER (PARTITION BY s.product_id ORDER BY s.price ASC) AS rn FROM product_skus s WHERE s.is_deleted = 0 AND s.enabled = 1 ) SELECT rp.merchant_id, rp.product_id AS spu_id, rp.product_name, rp.main_image, lps.price, lps.original_price FROM RankedProducts rp JOIN LowestPriceSku lps ON rp.product_id = lps.product_id AND lps.rn = 1 WHERE rp.rn <= 5 ORDER BY rp.merchant_id, rp.sort_weight DESC, rp.updated_time DESC;
